package org.fribok.bookkeeping.dataformat;

import se.swedsoft.bookkeeping.data.*;
import se.swedsoft.bookkeeping.data.base.SSSaleRow;

import java.math.BigDecimal;
import java.sql.*;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.*;

/** Converts customer invoice snapshots, ordered rows, and embedded vouchers. */
public final class CustomerCreditInvoiceStagingConverter {
 public ConversionResult convert(Connection legacy,Connection normalized)throws SQLException{Snapshot source=readLegacy(Objects.requireNonNull(legacy));SemanticFingerprint sf=fingerprint(source);try{writeNormalized(Objects.requireNonNull(normalized),source);Snapshot dest=readNormalized(normalized);SemanticFingerprint df=fingerprint(dest);List<String>d=sf.differences(df);if(!d.isEmpty()){normalized.rollback();throw new SQLException("Customer-credit-invoice staging fingerprint mismatch: "+String.join("; ",d));}normalized.commit();return new ConversionResult(sf,df,source.invoices.size(),source.addresses.size(),source.accounts.size(),source.rows.size(),source.vouchers.size(),source.voucherRows.size(),source.gaps,source.overlaps);}catch(SQLException|RuntimeException e){normalized.rollback();throw e;}}
 public SemanticFingerprint fingerprintNormalized(Connection c)throws SQLException{return fingerprint(readNormalized(c));}
 private static Snapshot readLegacy(Connection c)throws SQLException{Snapshot s=new Snapshot();query(c,"SELECT id,companyid,number,creditinvoice FROM tbl_creditinvoice ORDER BY companyid,id",r->{int id=r.getInt(1),company=r.getInt(2);Integer key=nullableInteger(r,3);SSCreditInvoice x=(SSCreditInvoice)r.getObject(4);if(!Objects.equals(key,x.getNumber()))throw new SQLException("Credit-invoice key/object mismatch for legacy id "+id+": table="+key+", object="+x.getNumber());List<BigDecimal>tax=x.getStoredTaxRates();s.invoices.add(new Invoice(id,company,key,x.getLocalDate(),x.getLocalDueDate(),x.getCustomerNr(),x.getCustomerName(),x.getOurContactPerson(),x.getYourContactPerson(),x.getCreditingNr(),x.getStoredDelayInterest(),x.getCurrency()==null?null:x.getCurrency().getName(),name(x.getPaymentTerm()),name(x.getDeliveryTerm()),name(x.getDeliveryWay()),x.getTaxFree(),x.getText(),tax.get(0),tax.get(1),tax.get(2),x.getEuSaleCommodity(),x.getEuSaleThirdPartCommodity(),x.isPrinted(),x.getStoredType()==null?null:x.getStoredType().name(),x.getCurrencyRate(),x.getYourOrderNumber(),x.getOCRNumber(),x.isEntered(),x.getNumReminders(),x.isInterestInvoiced(),x.isStockInfluencing(),x.getOrderNumbers()));addAddress(s,id,company,"invoice",x.getInvoiceAddress());addAddress(s,id,company,"delivery",x.getDeliveryAddress());x.getDefaultAccounts().entrySet().stream().sorted(Map.Entry.comparingByKey(Comparator.comparing(Enum::name))).forEach(e->s.accounts.add(new Account(id,e.getKey().name(),e.getValue())));int n=0;for(SSSaleRow row:x.getRows()){row.fixResultUnitAndProject();s.rows.add(new SaleLine(id,company,n++,row.getProductNr(),row.getDescription(),row.getUnitprice(),row.getQuantity(),row.getUnit()==null?null:row.getUnit().getName(),row.getDiscount(),row.getTaxCode()==null?null:row.getTaxCode().name(),row.getAccountNr(),row.getProjectNr(),row.getResultUnitNr()));}SSVoucher v=x.getStoredVoucher();if(v!=null){s.vouchers.add(new Voucher(id,v.getNumber(),v.getLocalDate(),v.getDescription()));int vr=0;for(SSVoucherRow row:v.getRows()){Instant edited=null;if(row.getLocalEditedDate()!=null){var res=LegacySwedishTimeResolver.resolve(row.getLocalEditedDate());edited=res.instant();if(res.kind()==LegacySwedishTimeResolver.ResolutionKind.FORWARD_BY_GAP)s.gaps++;else if(res.kind()==LegacySwedishTimeResolver.ResolutionKind.EARLIER_OFFSET_IN_OVERLAP)s.overlaps++;}s.voucherRows.add(new VoucherLine(id,vr++,row.getAccountNr(),row.getProjectNr(),row.getResultUnitNr(),row.getDebet(),row.getCredit(),edited,row.getEditedSignature(),row.isCrossed(),row.isAdded()));}}});s.sort();return s;}
 private static void writeNormalized(Connection c,Snapshot s)throws SQLException{for(Invoice r:s.invoices){try(PreparedStatement p=c.prepareStatement("INSERT INTO customer_credit_invoice (legacy_id,company_id,number,crediting_invoice_number,invoice_date,due_date,customer_number,customer_name,our_contact_person,customer_contact_person,delay_interest,currency_code,payment_term_name,delivery_term_name,delivery_way_name,tax_free,invoice_text,tax_rate_1,tax_rate_2,tax_rate_3,eu_sale_commodity,eu_sale_third_party_commodity,printed,invoice_type,currency_rate,customer_order_number,ocr_number,entered,reminder_count,interest_invoiced,stock_influencing,order_numbers) SELECT ?,id,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,? FROM company WHERE legacy_id=?",Statement.RETURN_GENERATED_KEYS)){int i=1;p.setInt(i++,r.legacyId);setInteger(p,i++,r.number);setInteger(p,i++,r.creditingNumber);p.setObject(i++,r.date);p.setObject(i++,r.dueDate);for(String v:r.firstStrings())p.setString(i++,v);p.setBigDecimal(i++,r.delayInterest);for(String v:r.lookups())p.setString(i++,v);p.setBoolean(i++,r.taxFree);p.setString(i++,r.text);p.setBigDecimal(i++,r.tax1);p.setBigDecimal(i++,r.tax2);p.setBigDecimal(i++,r.tax3);p.setBoolean(i++,r.euCommodity);p.setBoolean(i++,r.euThird);p.setBoolean(i++,r.printed);p.setString(i++,r.type);p.setBigDecimal(i++,r.currencyRate);p.setString(i++,r.orderNumber);p.setString(i++,r.ocr);p.setBoolean(i++,r.entered);p.setInt(i++,r.reminders);p.setBoolean(i++,r.interest);p.setBoolean(i++,r.stock);p.setString(i++,r.orderNumbers);p.setInt(i,r.companyLegacyId);if(p.executeUpdate()!=1)throw new SQLException("Missing company "+r.companyLegacyId+" for invoice "+r.legacyId);r.normalizedId=key(p);}}Map<Integer,Invoice>map=new HashMap<>();for(Invoice r:s.invoices)map.put(r.legacyId,r);for(Address r:s.addresses){Invoice x=req(map,r.invoiceLegacyId);try(PreparedStatement p=c.prepareStatement("INSERT INTO customer_credit_invoice_address VALUES (?,?,?,?,?,?,?,?,?)")){p.setLong(1,x.normalizedId);p.setLong(2,companyId(c,x.companyLegacyId));p.setString(3,r.type);int i=4;for(String v:r.values())p.setString(i++,v);p.executeUpdate();}}for(Account r:s.accounts){Invoice x=req(map,r.invoiceLegacyId);try(PreparedStatement p=c.prepareStatement("INSERT INTO customer_credit_invoice_default_account VALUES (?,?,?)")){p.setLong(1,x.normalizedId);p.setString(2,r.type);setInteger(p,3,r.number);p.executeUpdate();}}for(SaleLine r:s.rows){Invoice x=req(map,r.invoiceLegacyId);try(PreparedStatement p=c.prepareStatement("INSERT INTO customer_credit_invoice_row VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)")){p.setLong(1,x.normalizedId);p.setLong(2,companyId(c,x.companyLegacyId));p.setInt(3,r.row);p.setString(4,r.product);p.setString(5,r.description);p.setBigDecimal(6,r.unitPrice);p.setBigDecimal(7,r.quantity);p.setString(8,r.unit);p.setBigDecimal(9,r.discount);p.setString(10,r.taxCode);setInteger(p,11,r.account);p.setString(12,r.project);p.setString(13,r.resultUnit);p.executeUpdate();}}for(Voucher r:s.vouchers){Invoice x=req(map,r.invoiceLegacyId);try(PreparedStatement p=c.prepareStatement("INSERT INTO customer_credit_invoice_voucher VALUES (?,?,?,?)")){p.setLong(1,x.normalizedId);p.setInt(2,r.number);p.setObject(3,r.date);p.setString(4,r.description);p.executeUpdate();}}for(VoucherLine r:s.voucherRows){Invoice x=req(map,r.invoiceLegacyId);try(PreparedStatement p=c.prepareStatement("INSERT INTO customer_credit_invoice_voucher_row VALUES (?,?,?,?,?,?,?,?,?,?,?)")){p.setLong(1,x.normalizedId);p.setInt(2,r.row);setInteger(p,3,r.account);p.setString(4,r.project);p.setString(5,r.resultUnit);p.setBigDecimal(6,r.debit);p.setBigDecimal(7,r.credit);p.setObject(8,r.edited==null?null:OffsetDateTime.ofInstant(r.edited,ZoneOffset.UTC));p.setString(9,r.signature);p.setBoolean(10,r.crossed);p.setBoolean(11,r.added);p.executeUpdate();}}}
 private static Snapshot readNormalized(Connection c)throws SQLException{Snapshot s=new Snapshot();query(c,"SELECT i.id,i.legacy_id,c.legacy_id,i.number,i.crediting_invoice_number,i.invoice_date,i.due_date,i.customer_number,i.customer_name,i.our_contact_person,i.customer_contact_person,i.delay_interest,i.currency_code,i.payment_term_name,i.delivery_term_name,i.delivery_way_name,i.tax_free,i.invoice_text,i.tax_rate_1,i.tax_rate_2,i.tax_rate_3,i.eu_sale_commodity,i.eu_sale_third_party_commodity,i.printed,i.invoice_type,i.currency_rate,i.customer_order_number,i.ocr_number,i.entered,i.reminder_count,i.interest_invoiced,i.stock_influencing,i.order_numbers FROM customer_credit_invoice i JOIN company c ON c.id=i.company_id ORDER BY c.legacy_id,i.id",r->{Invoice x=new Invoice(r.getInt(2),r.getInt(3),nullableInteger(r,4),r.getObject(6,java.time.LocalDate.class),r.getObject(7,java.time.LocalDate.class),r.getString(8),r.getString(9),r.getString(10),r.getString(11),nullableInteger(r,5),r.getBigDecimal(12),r.getString(13),r.getString(14),r.getString(15),r.getString(16),r.getBoolean(17),r.getString(18),r.getBigDecimal(19),r.getBigDecimal(20),r.getBigDecimal(21),r.getBoolean(22),r.getBoolean(23),r.getBoolean(24),r.getString(25),r.getBigDecimal(26),r.getString(27),r.getString(28),r.getBoolean(29),r.getInt(30),r.getBoolean(31),r.getBoolean(32),r.getString(33));x.normalizedId=r.getLong(1);s.invoices.add(x);});query(c,"SELECT i.legacy_id,c.legacy_id,a.address_type,a.name,a.address_line_1,a.address_line_2,a.postal_code,a.city,a.country FROM customer_credit_invoice_address a JOIN customer_credit_invoice i ON i.id=a.credit_invoice_id JOIN company c ON c.id=a.company_id ORDER BY i.legacy_id,a.address_type",r->s.addresses.add(new Address(r.getInt(1),r.getInt(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9))));query(c,"SELECT i.legacy_id,a.account_type,a.account_number FROM customer_credit_invoice_default_account a JOIN customer_credit_invoice i ON i.id=a.credit_invoice_id ORDER BY i.legacy_id,a.account_type",r->s.accounts.add(new Account(r.getInt(1),r.getString(2),nullableInteger(r,3))));query(c,"SELECT i.legacy_id,c.legacy_id,x.row_number,x.product_number,x.description,x.unit_price,x.quantity,x.unit_name,x.discount,x.tax_code,x.account_number,x.project_number,x.result_unit_number FROM customer_credit_invoice_row x JOIN customer_credit_invoice i ON i.id=x.credit_invoice_id JOIN company c ON c.id=x.company_id ORDER BY i.legacy_id,x.row_number",r->s.rows.add(new SaleLine(r.getInt(1),r.getInt(2),r.getInt(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getString(8),r.getBigDecimal(9),r.getString(10),nullableInteger(r,11),r.getString(12),r.getString(13))));query(c,"SELECT i.legacy_id,v.number,v.voucher_date,v.description FROM customer_credit_invoice_voucher v JOIN customer_credit_invoice i ON i.id=v.credit_invoice_id ORDER BY i.legacy_id",r->s.vouchers.add(new Voucher(r.getInt(1),r.getInt(2),r.getObject(3,java.time.LocalDate.class),r.getString(4))));query(c,"SELECT i.legacy_id,x.row_number,x.account_number,x.project_number,x.result_unit_number,x.debit,x.credit,x.edited_at,x.edited_signature,x.crossed,x.added FROM customer_credit_invoice_voucher_row x JOIN customer_credit_invoice i ON i.id=x.credit_invoice_id ORDER BY i.legacy_id,x.row_number",r->s.voucherRows.add(new VoucherLine(r.getInt(1),r.getInt(2),nullableInteger(r,3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getObject(8)==null?null:r.getObject(8,OffsetDateTime.class).toInstant(),r.getString(9),r.getBoolean(10),r.getBoolean(11))));s.sort();return s;}
 private static SemanticFingerprint fingerprint(Snapshot s){SemanticFingerprintBuilder b=new SemanticFingerprintBuilder();var d=b.domain("customer-credit-invoices");for(Invoice r:s.invoices){var w=d.startRecord(r.companyLegacyId+"/"+r.legacyId).writeInteger(r.legacyId).writeInteger(r.companyLegacyId).writeInteger(r.number).writeInteger(r.creditingNumber).writeDate(r.date).writeDate(r.dueDate);for(String v:r.firstStrings())w.writeString(v);w.writeDecimal(canon(r.delayInterest));for(String v:r.lookups())w.writeString(v);w.writeBoolean(r.taxFree).writeString(r.text).writeDecimal(canon(r.tax1)).writeDecimal(canon(r.tax2)).writeDecimal(canon(r.tax3)).writeBoolean(r.euCommodity).writeBoolean(r.euThird).writeBoolean(r.printed).writeString(r.type).writeDecimal(canon(r.currencyRate)).writeString(r.orderNumber).writeString(r.ocr).writeBoolean(r.entered).writeInteger(r.reminders).writeBoolean(r.interest).writeBoolean(r.stock).writeString(r.orderNumbers);}d.finish();fingerprintAddresses(b,s);fingerprintAccounts(b,s);fingerprintRows(b,s);fingerprintVouchers(b,s);return b.finish();}
 private static void fingerprintAddresses(SemanticFingerprintBuilder b,Snapshot s){var d=b.domain("customer-credit-invoice-addresses");for(Address r:s.addresses){var w=d.startRecord(r.invoiceLegacyId+"/"+r.type).writeInteger(r.invoiceLegacyId).writeInteger(r.companyLegacyId).writeString(r.type);for(String v:r.values())w.writeString(v);}d.finish();}private static void fingerprintAccounts(SemanticFingerprintBuilder b,Snapshot s){var d=b.domain("customer-credit-invoice-default-accounts");for(Account r:s.accounts)d.startRecord(r.invoiceLegacyId+"/"+r.type).writeInteger(r.invoiceLegacyId).writeString(r.type).writeInteger(r.number);d.finish();}private static void fingerprintRows(SemanticFingerprintBuilder b,Snapshot s){var d=b.domain("customer-credit-invoice-rows");for(SaleLine r:s.rows)d.startRecord(r.invoiceLegacyId+"/"+r.row).writeInteger(r.invoiceLegacyId).writeInteger(r.companyLegacyId).writeInteger(r.row).writeString(r.product).writeString(r.description).writeDecimal(canon(r.unitPrice)).writeDecimal(canon(r.quantity)).writeString(r.unit).writeDecimal(canon(r.discount)).writeString(r.taxCode).writeInteger(r.account).writeString(r.project).writeString(r.resultUnit);d.finish();}private static void fingerprintVouchers(SemanticFingerprintBuilder b,Snapshot s){var v=b.domain("customer-credit-invoice-vouchers");for(Voucher r:s.vouchers)v.startRecord(Integer.toString(r.invoiceLegacyId)).writeInteger(r.invoiceLegacyId).writeInteger(r.number).writeDate(r.date).writeString(r.description);v.finish();var d=b.domain("customer-credit-invoice-voucher-rows");for(VoucherLine r:s.voucherRows)d.startRecord(r.invoiceLegacyId+"/"+r.row).writeInteger(r.invoiceLegacyId).writeInteger(r.row).writeInteger(r.account).writeString(r.project).writeString(r.resultUnit).writeDecimal(canon(r.debit)).writeDecimal(canon(r.credit)).writeInstant(r.edited).writeString(r.signature).writeBoolean(r.crossed).writeBoolean(r.added).addDebit(canon(r.debit)).addCredit(canon(r.credit));d.finish();}
 private static void addAddress(Snapshot s,int invoice,int company,String type,SSAddress a){if(a!=null)s.addresses.add(new Address(invoice,company,type,a.getName(),a.getAddress1(),a.getAddress2(),a.getZipCode(),a.getCity(),a.getCountry()));}private static String name(Object v){if(v instanceof se.swedsoft.bookkeeping.data.common.SSPaymentTerm x)return x.getName();if(v instanceof se.swedsoft.bookkeeping.data.common.SSDeliveryTerm x)return x.getName();if(v instanceof se.swedsoft.bookkeeping.data.common.SSDeliveryWay x)return x.getName();return null;}private static BigDecimal canon(BigDecimal v){return v==null?null:v.signum()==0?BigDecimal.ZERO:v.stripTrailingZeros();}private static void setInteger(PreparedStatement p,int i,Integer v)throws SQLException{if(v==null)p.setNull(i,Types.INTEGER);else p.setInt(i,v);}private static Integer nullableInteger(ResultSet r,int i)throws SQLException{int v=r.getInt(i);return r.wasNull()?null:v;}private static long key(PreparedStatement p)throws SQLException{try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Missing generated credit-invoice key");return r.getLong(1);}}private static long companyId(Connection c,int legacy)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id FROM company WHERE legacy_id=?")){p.setInt(1,legacy);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Missing company "+legacy);return r.getLong(1);}}}private static <K,V>V req(Map<K,V>m,K k)throws SQLException{V v=m.get(k);if(v==null)throw new SQLException("Missing credit-invoice mapping "+k);return v;}private static void query(Connection c,String sql,SqlRow f)throws SQLException{try(Statement p=c.createStatement();ResultSet r=p.executeQuery(sql)){while(r.next())f.accept(r);}}
 public record ConversionResult(SemanticFingerprint sourceFingerprint,SemanticFingerprint destinationFingerprint,long invoices,long addresses,long defaultAccounts,long rows,long vouchers,long voucherRows,long daylightSavingGapAdjustments,long daylightSavingOverlapResolutions){}@FunctionalInterface private interface SqlRow{void accept(ResultSet r)throws SQLException;}
 private static final class Invoice{final int legacyId,companyLegacyId;final Integer number;final java.time.LocalDate date,dueDate;final String customerNumber,customerName,ourContact,customerContact;final Integer creditingNumber;final BigDecimal delayInterest;final String currency,paymentTerm,deliveryTerm,deliveryWay;final boolean taxFree;final String text;final BigDecimal tax1,tax2,tax3;final boolean euCommodity,euThird,printed;final String type;final BigDecimal currencyRate;final String orderNumber,ocr;final boolean entered;final int reminders;final boolean interest,stock;final String orderNumbers;long normalizedId;Invoice(int legacyId,int companyLegacyId,Integer number,java.time.LocalDate date,java.time.LocalDate dueDate,String customerNumber,String customerName,String ourContact,String customerContact,Integer creditingNumber,BigDecimal delayInterest,String currency,String paymentTerm,String deliveryTerm,String deliveryWay,boolean taxFree,String text,BigDecimal tax1,BigDecimal tax2,BigDecimal tax3,boolean euCommodity,boolean euThird,boolean printed,String type,BigDecimal currencyRate,String orderNumber,String ocr,boolean entered,int reminders,boolean interest,boolean stock,String orderNumbers){this.legacyId=legacyId;this.companyLegacyId=companyLegacyId;this.number=number;this.date=date;this.dueDate=dueDate;this.customerNumber=customerNumber;this.customerName=customerName;this.ourContact=ourContact;this.customerContact=customerContact;this.creditingNumber=creditingNumber;this.delayInterest=delayInterest;this.currency=currency;this.paymentTerm=paymentTerm;this.deliveryTerm=deliveryTerm;this.deliveryWay=deliveryWay;this.taxFree=taxFree;this.text=text;this.tax1=tax1;this.tax2=tax2;this.tax3=tax3;this.euCommodity=euCommodity;this.euThird=euThird;this.printed=printed;this.type=type;this.currencyRate=currencyRate;this.orderNumber=orderNumber;this.ocr=ocr;this.entered=entered;this.reminders=reminders;this.interest=interest;this.stock=stock;this.orderNumbers=orderNumbers;}List<String>firstStrings(){return Arrays.asList(customerNumber,customerName,ourContact,customerContact);}List<String>lookups(){return Arrays.asList(currency,paymentTerm,deliveryTerm,deliveryWay);}}
 private record Address(int invoiceLegacyId,int companyLegacyId,String type,String name,String line1,String line2,String postal,String city,String country){List<String>values(){return Arrays.asList(name,line1,line2,postal,city,country);}}private record Account(int invoiceLegacyId,String type,Integer number){}private record SaleLine(int invoiceLegacyId,int companyLegacyId,int row,String product,String description,BigDecimal unitPrice,BigDecimal quantity,String unit,BigDecimal discount,String taxCode,Integer account,String project,String resultUnit){}private record Voucher(int invoiceLegacyId,int number,java.time.LocalDate date,String description){}private record VoucherLine(int invoiceLegacyId,int row,Integer account,String project,String resultUnit,BigDecimal debit,BigDecimal credit,Instant edited,String signature,boolean crossed,boolean added){}
 private static final class Snapshot{final List<Invoice>invoices=new ArrayList<>();final List<Address>addresses=new ArrayList<>();final List<Account>accounts=new ArrayList<>();final List<SaleLine>rows=new ArrayList<>();final List<Voucher>vouchers=new ArrayList<>();final List<VoucherLine>voucherRows=new ArrayList<>();long gaps,overlaps;void sort(){invoices.sort(Comparator.comparingInt((Invoice r)->r.companyLegacyId).thenComparingInt(r->r.legacyId));addresses.sort(Comparator.comparingInt(Address::invoiceLegacyId).thenComparing(Address::type));accounts.sort(Comparator.comparingInt(Account::invoiceLegacyId).thenComparing(Account::type));rows.sort(Comparator.comparingInt(SaleLine::invoiceLegacyId).thenComparingInt(SaleLine::row));vouchers.sort(Comparator.comparingInt(Voucher::invoiceLegacyId));voucherRows.sort(Comparator.comparingInt(VoucherLine::invoiceLegacyId).thenComparingInt(VoucherLine::row));}}
}
